import json, pathlib, subprocess, tempfile, textwrap; repo = pathlib.Path.cwd();

def write_project(name, source):
    root = pathlib.Path(tempfile.mkdtemp(prefix=f'fozzylang-{name}-'))
    (root / 'src').mkdir(parents=True, exist_ok=True)
    (root / 'fozzy.toml').write_text(textwrap.dedent(f'''\
        [package]
        name="{name}"
        version="0.1.0"

        [[target.bin]]
        name="{name}"
        path="src/main.fzy"
    '''))
    (root / 'src/main.fzy').write_text(textwrap.dedent(source))
    return root

def verify(name, source, expect_rc):
    root = write_project(name, source)
    proc = subprocess.run(['cargo', 'run', '-q', '-p', 'fz', '--', 'verify', str(root), '--json'], cwd=str(repo), capture_output=True, text=True)
    payload = json.loads(proc.stdout.strip())
    assert proc.returncode == expect_rc, (name, proc.returncode, payload, proc.stderr)
    return payload

def messages(payload):
    return [item['message'] for item in payload['items']]

kernel_return_fail = verify('gpu_kernel_return_fail', '''
    kernel fn launch() -> i32 {
        return 7;
    }
''', 1)
assert any('kernel function `launch` must return `void`' in message for message in messages(kernel_return_fail)), kernel_return_fail

kernel_host_call_fail = verify('gpu_kernel_host_call_fail', '''
    host fn load() -> i32 {
        return 1;
    }
    kernel fn launch() -> void {
        discard load();
    }
''', 1)
assert any('kernel function `launch` cannot call host function `load`' in message for message in messages(kernel_host_call_fail)), kernel_host_call_fail

pure_gpu_fail = verify('gpu_pure_api_fail', '''
    use core.gpu;
    pure fn bad() -> i32 {
        return gpu.device_count();
    }
    fn main() -> i32 {
        return bad();
    }
''', 1)
assert any('pure function `bad` cannot call GPU API `gpu.device_count`' in message for message in messages(pure_gpu_fail)), pure_gpu_fail

host_gpu_pass = verify('gpu_host_capability_pass', '''
    use core.gpu;
    host fn main() -> i32 {
        discard gpu.device_count();
        return 0;
    }
''', 0)
assert host_gpu_pass['errors'] == 0, host_gpu_pass

gpu_linear_fail = verify('gpu_linear_fail', '''
    use core.gpu;
    host fn main() -> i32 {
        let dev = gpu.default_device();
        let buf = gpu.alloc_f32(dev, 8);
        discard gpu.device_name(dev);
        return 0;
    }
''', 1)
assert any('linear value `buf` was not consumed/freed' in message for message in messages(gpu_linear_fail)), gpu_linear_fail

host_device_intrinsic_fail = verify('gpu_host_calls_device_intrinsic', '''
    host fn main() -> i32 {
        return gpu.global_id_x();
    }
''', 1)
assert any('host function `main` cannot call device-only GPU intrinsic `gpu.global_id_x`' in message for message in messages(host_device_intrinsic_fail)), host_device_intrinsic_fail

device_type_fail = verify('gpu_device_type_fail', '''
    device fn bad(buffer: GpuBuffer<f32>) -> i32 {
        discard buffer;
        return 0;
    }
''', 1)
assert any('device function `bad` parameter `buffer` uses unsupported device type `GpuBuffer<f32>`' in message for message in messages(device_type_fail)), device_type_fail

print('compiler-gpu-execution-spaces-ok')

